import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runPhase as before } from '../case/before/src/runner.mjs';
import { runPhase as after } from '../case/after/src/runner.mjs';
const expected = { runId: 'r-382', attempt: 3 };
const observation = JSON.parse(await readFile(new URL('../case/evidence/observation-01.json', import.meta.url), 'utf8'));
const make = (status, conclusion) => ({run_id:'r-382',attempt:3,jobs:[{steps:[{status,conclusion}]}]});
async function dispatch(runPhase, body) {
  let calls=0;
  const result=await runPhase(async()=>structuredClone(body),expected,async()=>{calls++;});
  return {result,calls};
}
for (const [name, fn] of [['before',before],['after',after]]) {
  test(name+': R-2 raw captured pending inventory invokes exactly once', async()=>{
    const observed=await dispatch(fn,observation);
    console.log(JSON.stringify({version:name,scenario:'captured pending inventory',observed}));
    assert.deepEqual(observed,{result:{admitted:true,commandCalls:1},calls:1});
  });
}
for (const status of ['queued','running','pending','completed','unknown']) {
  for (const conclusion of [null,'success','skipped','failure','cancelled']) {
    const allow = status==='completed' ? ['success','skipped'].includes(conclusion) : ['queued','running','pending'].includes(status) && conclusion===null;
    test(`after: R-1/R-2/R-3 ${status}/${conclusion} => ${allow ? 'one command' : 'no command'}`,async()=>{
      const observed=await dispatch(after,make(status,conclusion));
      assert.deepEqual(observed,{result:{admitted:allow,commandCalls:allow?1:0},calls:allow?1:0});
    });
  }
}
const refusalCases = [
 ['different run ID',{...make('queued',null),run_id:'r-383'}],
 ['different attempt',{...make('queued',null),attempt:2}],
 ['string attempt',{...make('queued',null),attempt:'3'}],
 ['missing snapshot',null],
 ['missing jobs',{run_id:'r-382',attempt:3}],
 ['non-array jobs',{run_id:'r-382',attempt:3,jobs:{}}],
 ['empty jobs',{run_id:'r-382',attempt:3,jobs:[]}],
 ['missing steps',{run_id:'r-382',attempt:3,jobs:[{}]}],
 ['empty steps',{run_id:'r-382',attempt:3,jobs:[{steps:[]}]}],
 ['non-array steps',{run_id:'r-382',attempt:3,jobs:[{steps:{}}]}],
 ['unknown state in mixed inventory',{run_id:'r-382',attempt:3,jobs:[{steps:[{status:'queued',conclusion:null},{status:'unknown',conclusion:null}]}]}],
 ['failed step in another job',{run_id:'r-382',attempt:3,jobs:[{steps:[{status:'queued',conclusion:null}]},{steps:[{status:'completed',conclusion:'failure'}]}]}],
 ['cancelled step in another job',{run_id:'r-382',attempt:3,jobs:[{steps:[{status:'queued',conclusion:null}]},{steps:[{status:'completed',conclusion:'cancelled'}]}]}]
];
for (const [name,body] of refusalCases) test('after: R-1/R-3 '+name,async()=>{
 const observed=await dispatch(after,body);
 assert.deepEqual(observed,{result:{admitted:false,commandCalls:0},calls:0});
});
test('after: R-2 complete admissible mixed inventory invokes exactly once',async()=>{
 const body={run_id:'r-382',attempt:3,jobs:[{steps:[{status:'completed',conclusion:'success'},{status:'queued',conclusion:null}]},{steps:[{status:'completed',conclusion:'skipped'},{status:'running',conclusion:null},{status:'pending',conclusion:null}]}]};
 const observed=await dispatch(after,body);
 console.log(JSON.stringify({version:'after',scenario:'complete admissible mixed inventory',observed}));
 assert.deepEqual(observed,{result:{admitted:true,commandCalls:1},calls:1});
});

