import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runPhase as after } from '../case/after/src/runner.mjs';
import { runPhase as before } from '../case/before/src/runner.mjs';
const expected = { runId: 'r-382', attempt: 3 };
const step = (status, conclusion) => ({ status, conclusion });
const body = (steps) => ({ run_id: expected.runId, attempt: expected.attempt, jobs: [{ steps }] });
let checks = 0;
async function verify(label, snapshot, allowed, { runner = after, allowThrownRejection = false } = {}) {
  let calls = 0;
  let reads = 0;
  let result, thrown;
  try { result = await runner(async () => { reads++; return snapshot; }, expected, async () => { calls++; }); }
  catch (error) { thrown = error; }
  assert.equal(reads, 1, `${label}: one acquisition`);
  assert.equal(calls, allowed ? 1 : 0, `${label}: actual dispatch count`);
  if (thrown) {
    assert.equal(allowed, false, `${label}: allowed request threw`);
    assert.equal(allowThrownRejection, true, `${label}: unexpected exception: ${thrown}`);
  } else {
    assert.deepEqual(result, { admitted: allowed, commandCalls: allowed ? 1 : 0 }, label);
  }
  checks++;
  console.log(JSON.stringify({ label, allowed, calls, result, rejection: thrown?.name }));
}
// The expected admission set comes from EP-17 revision 5, not provider state breadth.
const statuses = ['queued', 'running', 'pending', 'completed', 'unknown', null, undefined];
const conclusions = [null, 'success', 'skipped', 'failure', 'cancelled', 'unknown', undefined];
for (const status of statuses) {
  for (const conclusion of conclusions) {
    const allowed = (status === 'completed' && ['success','skipped'].includes(conclusion)) ||
      (['queued','running'].includes(status) && conclusion === null);
    await verify(`state=${String(status)},conclusion=${String(conclusion)}`, body([step(status, conclusion)]), allowed);
  }
}
const admissible = [step('queued', null), step('running', null), step('completed', 'success'), step('completed', 'skipped')];
await verify('mixed accepted states across multiple jobs', {
  ...body(admissible), jobs: [{ steps: admissible.slice(0, 2) }, { steps: admissible.slice(2) }]
}, true);
for (const denied of [step('pending', null), step('completed', 'failure'), step('completed', 'cancelled'), step('completed', null), step('running', 'success'), step('unknown', null)]) {
  for (const position of ['first', 'last']) {
    const steps = position === 'first' ? [denied, ...admissible] : [...admissible, denied];
    await verify(`mixed denied ${denied.status}/${String(denied.conclusion)} ${position}`, {
      ...body(steps), jobs: [{ steps: admissible }, { steps }]
    }, false);
  }
}
for (const [field, value] of [['run_id','r-383'],['run_id',382],['run_id',null],['run_id',''],['attempt',2],['attempt','3'],['attempt',null],['attempt',0]]) {
  await verify(`binding ${field}=${JSON.stringify(value)}`, { ...body(admissible), [field]: value }, false);
}
const malformed = [
  ['null snapshot', null],
  ['missing inventory', { run_id: expected.runId, attempt: expected.attempt }],
  ['null jobs', { ...body(admissible), jobs: null }],
  ['object jobs', { ...body(admissible), jobs: {} }],
  ['empty jobs', { ...body(admissible), jobs: [] }],
  ['missing steps', { ...body(admissible), jobs: [{}] }],
  ['null steps', body(null)],
  ['object steps', body({})],
  ['empty steps', body([])],
  ['null job', { ...body(admissible), jobs: [null] }],
  ['null step', body([null])],
  ['missing step fields', body([{}])]
];
for (const [label, snapshot] of malformed) {
  // EP-17 requires rejection and no dispatch, but does not specify an exception/return shape.
  await verify(`malformed: ${label}`, snapshot, false, { allowThrownRejection: true });
}
const capture = JSON.parse(await readFile(new URL('../case/evidence/observation-01.json', import.meta.url)));
await verify('raw capture containing pending: after must deny', capture, false);
// Observe exactly what the patch changes; these base checks are not policy assertions for after.
await verify('base accepts raw pending capture', capture, true, { runner: before });
await verify('base accepts unknown state', body([step('unknown', null)]), true, { runner: before });
console.log(`PASS ${checks} boundary checks; expected policy rows validated using real local runPhase dispatch.`);

