import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runPhase } from '../case/after/src/runner.mjs';
import { runPhase as runBefore } from '../case/before/src/runner.mjs';

// Oracle: approved EP-17 r4 R-1/R-2/R-3 plus Batchline API 2.3 wire states.
// Expected values below are specified independently of the client predicates.
const expected = { runId: 'r-382', attempt: 3 };
const step = (status, conclusion) => ({ status, conclusion });
const inventory = steps => ({ run_id: expected.runId, attempt: expected.attempt, jobs: [{ steps }] });
const allowedSteps = [step('completed', 'success'), step('completed', 'skipped'), step('queued', null), step('running', null), step('pending', null)];
let checked = 0;

async function check(body, admitted, runner = runPhase) {
  let calls = 0;
  const result = await runner(async () => body, expected, async () => { calls++; });
  assert.deepEqual(result, { admitted, commandCalls: admitted ? 1 : 0 }, JSON.stringify(body));
  assert.equal(calls, admitted ? 1 : 0, JSON.stringify(body));
  checked++;
}

function sequences(n, prefix = []) {
  if (n === 0) return [prefix];
  return allowedSteps.flatMap(value => sequences(n - 1, [...prefix, value]));
}

test('R-2 / allow: all length 1-3 sequences, one job and one step per job', async () => {
  let cases = 0;
  for (let length = 1; length <= 3; length++) {
    for (const steps of sequences(length)) {
      await check(inventory(steps), true);
      await check({ run_id: expected.runId, attempt: expected.attempt, jobs: steps.map(value => ({ steps: [value] })) }, true);
      cases += 2;
    }
  }
  console.log(JSON.stringify({ row: 'allow', cases }));
});

test('R-1/R-3 / deny: disallowed conclusions and unknown states in every inventory position', async () => {
  const deniedSteps = [];
  for (const status of ['queued', 'running', 'pending']) {
    for (const conclusion of ['success', 'skipped', 'failure', 'cancelled', undefined, '', 0, false]) deniedSteps.push(step(status, conclusion));
  }
  for (const conclusion of ['failure', 'cancelled', null, undefined, '', 0, false]) deniedSteps.push(step('completed', conclusion));
  for (const status of ['unknown', '', undefined, null, 0, false]) deniedSteps.push(step(status, null));
  let cases = 0;
  for (const denied of deniedSteps) {
    for (let position = 0; position < 3; position++) {
      const steps = [allowedSteps[0], allowedSteps[4]];
      steps.splice(position, 0, denied);
      await check(inventory(steps), false);
      await check({ run_id: expected.runId, attempt: expected.attempt, jobs: steps.map(value => ({ steps: [value] })) }, false);
      cases += 2;
    }
  }
  console.log(JSON.stringify({ row: 'deny-state-or-conclusion', cases }));
});

test('R-1 / deny: identity mismatch, absent, and incorrect wire types', async () => {
  let cases = 0;
  for (const run_id of ['r-383', '', undefined, null, 382]) {
    await check({ ...inventory([allowedSteps[4]]), run_id }, false);
    cases++;
  }
  for (const attempt of [2, 4, '3', undefined, null, 0, -1, 3.5]) {
    await check({ ...inventory([allowedSteps[4]]), attempt }, false);
    cases++;
  }
  console.log(JSON.stringify({ row: 'deny-identity', cases }));
});

test('R-1 / malformed or empty inventory rejects without command dispatch', async () => {
  const base = { run_id: expected.runId, attempt: expected.attempt };
  const malformed = [
    null, undefined, false, 3, 'body', [], {}, base,
    { ...base, jobs: null }, { ...base, jobs: {} }, { ...base, jobs: [] },
    { ...base, jobs: [{}] }, { ...base, jobs: [{ steps: null }] },
    { ...base, jobs: [{ steps: {} }] }, { ...base, jobs: [{ steps: [] }] },
    { ...base, jobs: [{ steps: [{}] }] },
    { ...base, jobs: [null] }, { ...base, jobs: [{ steps: [null] }] },
    { ...base, jobs: [{ steps: [allowedSteps[0]] }, null] },
    { ...base, jobs: [{ steps: [allowedSteps[0], null] }] }
  ];
  const observations = [];
  for (const [index, body] of malformed.entries()) {
    let calls = 0;
    let result;
    let thrown;
    try { result = await runPhase(async () => body, expected, async () => { calls++; }); }
    catch (error) { thrown = { name: error.name, message: error.message }; }
    assert.equal(calls, 0, `malformed case ${index}`);
    if (!thrown) assert.deepEqual(result, { admitted: false, commandCalls: 0 });
    observations.push({ index, input: body, result, thrown, calls });
    checked++;
  }
  // EP-17 requires rejection/no admission, but does not prescribe the return
  // or exception shape for malformed nested values; record that distinction.
  console.log(JSON.stringify({ row: 'deny-malformed', cases: malformed.length, observations }));
});

test('R-2 / supplied raw provider capture is admitted with exactly one command call', async () => {
  const body = JSON.parse(await readFile(new URL('../case/evidence/observation-01.json', import.meta.url)));
  await check(body, true);
});

test('before/after delta: unknown rejected; pending admission preserved', async () => {
  await check(inventory([step('unknown', null)]), true, runBefore);
  await check(inventory([step('unknown', null)]), false);
  await check(inventory([step('pending', null)]), true, runBefore);
  await check(inventory([step('pending', null)]), true);
  console.log(JSON.stringify({ checked }));
});

